type Seed = Partial<GuideStop> & {
  id: string;
  name: string;
  coordinates: [number, number];
  description: string;
  hours: NonNullable<GuideStop["hours"]>;
  officialUrl: string;
  image?: string;
  editorialUrls?: string[];
};

function stop(seed: Seed): GuideStop {
  const { image = photoSources[seed.name] ?? commons("Panorama of Tbilisi, Georgia.jpg"), editorialUrls = [], sourceUrls = [], ...rest } = seed;
  const mapUrl = maps(`${seed.name} Tbilisi Georgia`);
  return {
    ...rest,
    photo: image,
    imageSourceUrl: image,
    sourceUrls: [...new Set([seed.officialUrl, mapUrl, image, ...editorialUrls, ...sourceUrls])],
    sourceEvidence: {
      officialUrl: seed.officialUrl,
      mapUrl,
      currentStatusUrl: mapUrl,
      imageSourceUrl: image,
      editorialUrls,
      checkedAt,
      notes: "Official or property source, current map status, published hours, category fit, and image-source candidate checked on 2026-08-20; closed, duplicate, logo-only, and placeholder candidates were rejected.",
    },
  };
}

